entries[72043] = { ["name"] = "Cocktail-Shaker", ["text"] = "Questgegenstand\nBenutzen: Kombiniert 1 Mondbeerensaft mit 1 prickelnden Marktgetränk, um einen Mondbeerenfizz zu erschaffen.\n\"Ein Behälter, in dem Getränke aller Art gemischt werden können.\"" }
entries[72044] = { ["name"] = "Mondbeerenfizz", ["text"] = "Questgegenstand\n\"Es ist fruchtig! Es ist spritzig!\"" }
